/**
 * One import run. Every field is optional, and the defaults are the cautious reading of
 * "fill in the reference prices": only models with no price at all, across the whole catalogue,
 * and keep the result.
 */
export interface ReferencePriceImportInput {
  /**
   * Also replace stored prices nobody has verified. A price a person has checked is
   * never replaced, with or without this. Without it, a model that already has any price
   * is left alone: refilling rates an operator may have adjusted is not what "import the
   * reference prices" should mean by default.
   */
  force?: boolean;
  /** Report what would happen and keep none of it. The report says so as well, because otherwise the counts read identically either way. */
  dry_run?: boolean;
  /**
   * Consider only these models. Omitted or empty means the whole catalogue.
   *
   * An id matching no model comes back as a skipped result naming it, rather than being
   * dropped: a caller's list goes stale in the ordinary course of things, and a run that
   * silently considers less than it was asked to leaves the caller believing otherwise.
   */
  model_ids?: string[];
}

/**
 * `priced` — had no price and now has the reference rates; `updated` — an unverified price differed and was replaced, which only `force` reaches;
 * `unchanged` — the stored price already equals the reference; `kept` — already priced, and `force` was not asked for; `verified` — a person has checked this price, so nothing may replace it;
 * `skipped` — no reference rate could be resolved, with the reason in `detail`.
 *
 * Under `dry_run` these are what a real run would reach, not what was stored.
 */
export type ReferencePriceImportResultOutcome =
  (typeof ReferencePriceImportResultOutcome)[keyof typeof ReferencePriceImportResultOutcome];

export const ReferencePriceImportResultOutcome = {
  priced: "priced",
  updated: "updated",
  unchanged: "unchanged",
  kept: "kept",
  verified: "verified",
  skipped: "skipped",
} as const;

export interface ReferencePriceImportResult {
  /** The model's slug, or the id that was asked for when no model of that id exists */
  model: string;
  /**
   * `priced` — had no price and now has the reference rates; `updated` — an unverified price differed and was replaced, which only `force` reaches;
   * `unchanged` — the stored price already equals the reference; `kept` — already priced, and `force` was not asked for; `verified` — a person has checked this price, so nothing may replace it;
   * `skipped` — no reference rate could be resolved, with the reason in `detail`.
   *
   * Under `dry_run` these are what a real run would reach, not what was stored.
   */
  outcome: ReferencePriceImportResultOutcome;
  /** Written to be read by a person — for a skip the reason, for a write the dataset entry that supplied the rates and how it matched */
  detail: string;
}

/**
 * What the run did, model by model.
 *
 * Every model considered appears exactly once, including the ones no price was written for.
 * A model quietly missing from this list would recreate the failure the import exists to
 * remove: a model that refuses traffic with no clue why.
 */
export interface ReferencePriceImportReport {
  /** The dataset the rates were read from, as recorded on every row it wrote */
  dataset: string;
  /** The day the dataset was taken, as recorded on every row it wrote */
  snapshot_date?: string;
  /** How many priced models the dataset holds, which is not how many of them matched anything here */
  entries?: number;
  /** Whether the run kept what it decided. It travels with the report because every other field reads identically either way. */
  dry_run: boolean;
  /**
   * The warning codes the run confirmed on the operator's behalf, being the ones the
   * interactive editor would have stopped on. Reported rather than left implicit: a bulk
   * write that silently accepts every warning is worth being able to see. Blockers are
   * never among them — a blocker means the row would not add up, which is not a decision
   * anybody gets to sign off.
   */
  acknowledged?: string[];
  results: ReferencePriceImportResult[];
}

